const viewMode = inArgs.viewMode;
const aras = window.aras;
if (viewMode !== 'notification') {
	return aras.evalMethod('OnShowItemDefault', inDom, inArgs);
}

const { navigationPanel, tabsContainer } = window.mainLayout;
const tocData = navigationPanel.nav.data;
const myDiscussion = tocData.get('com.aras.innovator.cui_default.toc_Discussion_13D6BC25C69D132305EF070EAC9C1E7D');
if (!myDiscussion) {
	return;
}

const { icon, label, startPage = '', parameters = '' } = myDiscussion;
const searchParams = new URLSearchParams(parameters);
searchParams.set('startBookmarkId', 'allmessages');
const url = `${startPage}?${searchParams.toString()}`;

aras.browserHelper.toggleSpinner(document, true);
tabsContainer.openPage(url, icon, label);
